/** void CreateApprenticeMon(struct Pokemon *mon, const struct Apprentice *src, u8 monId) */
export function CreateApprenticeMon(mon: any, src: any, monId: any): any {
  let i: any = null;
      let evAmount: any = null;
      let language: any = null;
      let otId: any = gApprentices[src.id].otId;
      let personality: any = ((gApprentices[src.id].otId >> 8) | ((gApprentices[src.id].otId & 0xFF) << 8))
                      + src.party[monId].species + src.number;

      CreateMon(mon,
                src.party[monId].species,
                GetFrontierEnemyMonLevel(src.lvlMode - 1),
                MAX_PER_STAT_IVS,
                TRUE,
                personality,
                OT_ID_PRESET,
                otId);

      SetMonData(mon, MON_DATA_HELD_ITEM,src.party[monId].item);
      for (i = 0; i < MAX_MON_MOVES; i++)
          SetMonMoveSlot(mon, src.party[monId].moves[i], i);

      evAmount = MAX_TOTAL_EVS / NUM_STATS;
      for (i = 0; i < NUM_STATS; i++)
          SetMonData(mon, MON_DATA_HP_EV + i,evAmount);

      language = src.language;
      SetMonData(mon, MON_DATA_LANGUAGE,language);
      SetMonData(mon, MON_DATA_OT_NAME, GetApprenticeNameInLanguage(src.id, language));
      CalculateMonStats(mon);
}

