/** static u16 CalculateBoxMonChecksum(struct BoxPokemon *boxMon) */
export function CalculateBoxMonChecksum(boxMon: any): any {
  let checksum: any = 0;
      let substruct0: any = GetSubstruct(boxMon, boxMon.personality, 0);
      let substruct1: any = GetSubstruct(boxMon, boxMon.personality, 1);
      let substruct2: any = GetSubstruct(boxMon, boxMon.personality, 2);
      let substruct3: any = GetSubstruct(boxMon, boxMon.personality, 3);
      let i: any = null;

      for (i = 0; i < ARRAY_COUNT(substruct0.raw); i++)
          checksum += substruct0.raw[i];

      for (i = 0; i < ARRAY_COUNT(substruct1.raw); i++)
          checksum += substruct1.raw[i];

      for (i = 0; i < ARRAY_COUNT(substruct2.raw); i++)
          checksum += substruct2.raw[i];

      for (i = 0; i < ARRAY_COUNT(substruct3.raw); i++)
          checksum += substruct3.raw[i];

      return checksum;
}

/** void CalculateMonStats(struct Pokemon *mon) */
export function CalculateMonStats(mon: any): any {
  let oldMaxHP: any = GetMonData(mon, MON_DATA_MAX_HP, NULL);
      let currentHP: any = GetMonData(mon, MON_DATA_HP, NULL);
      let hpIV: any = GetMonData(mon, MON_DATA_HP_IV, NULL);
      let hpEV: any = GetMonData(mon, MON_DATA_HP_EV, NULL);
      let attackIV: any = GetMonData(mon, MON_DATA_ATK_IV, NULL);
      let attackEV: any = GetMonData(mon, MON_DATA_ATK_EV, NULL);
      let defenseIV: any = GetMonData(mon, MON_DATA_DEF_IV, NULL);
      let defenseEV: any = GetMonData(mon, MON_DATA_DEF_EV, NULL);
      let speedIV: any = GetMonData(mon, MON_DATA_SPEED_IV, NULL);
      let speedEV: any = GetMonData(mon, MON_DATA_SPEED_EV, NULL);
      let spAttackIV: any = GetMonData(mon, MON_DATA_SPATK_IV, NULL);
      let spAttackEV: any = GetMonData(mon, MON_DATA_SPATK_EV, NULL);
      let spDefenseIV: any = GetMonData(mon, MON_DATA_SPDEF_IV, NULL);
      let spDefenseEV: any = GetMonData(mon, MON_DATA_SPDEF_EV, NULL);
      let species: any = GetMonData(mon, MON_DATA_SPECIES, NULL);
      let level: any = GetLevelFromMonExp(mon);
      let newMaxHP: any = null;

      SetMonData(mon, MON_DATA_LEVEL,level);

      if (species == SPECIES_SHEDINJA)
      {
          newMaxHP = 1;
      }
      else
      {
          let n: any = 2 * gSpeciesInfo[species].baseHP + hpIV;
          newMaxHP = (((n + hpEV / 4) * level) / 100) + level + 10;
      }

      gBattleScripting.levelUpHP = newMaxHP - oldMaxHP;
      if (gBattleScripting.levelUpHP == 0)
          gBattleScripting.levelUpHP = 1;

      SetMonData(mon, MON_DATA_MAX_HP,newMaxHP);

      CALC_STAT(baseAttack, attackIV, attackEV, STAT_ATK, MON_DATA_ATK)
      CALC_STAT(baseDefense, defenseIV, defenseEV, STAT_DEF, MON_DATA_DEF)
      CALC_STAT(baseSpeed, speedIV, speedEV, STAT_SPEED, MON_DATA_SPEED)
      CALC_STAT(baseSpAttack, spAttackIV, spAttackEV, STAT_SPATK, MON_DATA_SPATK)
      CALC_STAT(baseSpDefense, spDefenseIV, spDefenseEV, STAT_SPDEF, MON_DATA_SPDEF)

      if (species == SPECIES_SHEDINJA)
      {
          if (currentHP != 0 || oldMaxHP == 0)
              currentHP = 1;
          else
              return;
      }
      else
      {
          if (currentHP == 0 && oldMaxHP == 0)
          {
              currentHP = newMaxHP;
          }
          else if (currentHP != 0)
          {
               
              currentHP += newMaxHP - oldMaxHP;
              if (currentHP <= 0)
                  currentHP = 1;
          }
          else
          {
              return;
          }
      }

      SetMonData(mon, MON_DATA_HP,currentHP);
}

/** void BoxMonToMon(const struct BoxPokemon *src, struct Pokemon *dest) */
export function BoxMonToMon(src: any, dest: any): any {
  let value: any = 0;
      dest.box = src;
      SetMonData(dest, MON_DATA_STATUS,value);
      SetMonData(dest, MON_DATA_HP,value);
      SetMonData(dest, MON_DATA_MAX_HP,value);
      value = MAIL_NONE;
      SetMonData(dest, MON_DATA_MAIL,value);
      CalculateMonStats(dest);
}

/** u8 GetLevelFromMonExp(struct Pokemon *mon) */
export function GetLevelFromMonExp(mon: any): any {
  let species: any = GetMonData(mon, MON_DATA_SPECIES, NULL);
      let exp: any = GetMonData(mon, MON_DATA_EXP, NULL);
      let level: any = 1;

      while (level <= MAX_LEVEL && gExperienceTables[gSpeciesInfo[species].growthRate][level] <= exp)
          level++;

      return level - 1;
}

/** u8 GetLevelFromBoxMonExp(struct BoxPokemon *boxMon) */
export function GetLevelFromBoxMonExp(boxMon: any): any {
  let species: any = GetBoxMonData(boxMon, MON_DATA_SPECIES, NULL);
      let exp: any = GetBoxMonData(boxMon, MON_DATA_EXP, NULL);
      let level: any = 1;

      while (level <= MAX_LEVEL && gExperienceTables[gSpeciesInfo[species].growthRate][level] <= exp)
          level++;

      return level - 1;
}

/** u16 GiveMoveToMon(struct Pokemon *mon, u16 move) */
export function GiveMoveToMon(mon: any, move: any): any {
  return GiveMoveToBoxMon(mon.box, move);
}

/** static u16 GiveMoveToBoxMon(struct BoxPokemon *boxMon, u16 move) */
export function GiveMoveToBoxMon(boxMon: any, move: any): any {
  let i: any = null;
      for (i = 0; i < MAX_MON_MOVES; i++)
      {
          let existingMove: any = GetBoxMonData(boxMon, MON_DATA_MOVE1 + i, NULL);
          if (existingMove == MOVE_NONE)
          {
              SetBoxMonData(boxMon, MON_DATA_MOVE1 + i,move);
              SetBoxMonData(boxMon, MON_DATA_PP1 + i,gBattleMoves[move].pp);
              return move;
          }
          if (existingMove == move)
              return MON_ALREADY_KNOWS_MOVE;
      }
      return MON_HAS_MAX_MOVES;
}

/** u16 GiveMoveToBattleMon(struct BattlePokemon *mon, u16 move) */
export function GiveMoveToBattleMon(mon: any, move: any): any {
  let i: any = null;

      for (i = 0; i < MAX_MON_MOVES; i++)
      {
          if (mon.moves[i] == MOVE_NONE)
          {
              mon.moves[i] = move;
              mon.pp[i] = gBattleMoves[move].pp;
              return move;
          }
      }

      return MON_HAS_MAX_MOVES;
}

/** void SetMonMoveSlot(struct Pokemon *mon, u16 move, u8 slot) */
export function SetMonMoveSlot(mon: any, move: any, slot: any): any {
  SetMonData(mon, MON_DATA_MOVE1 + slot,move);
      SetMonData(mon, MON_DATA_PP1 + slot,gBattleMoves[move].pp);
}

/** void SetBattleMonMoveSlot(struct BattlePokemon *mon, u16 move, u8 slot) */
export function SetBattleMonMoveSlot(mon: any, move: any, slot: any): any {
  mon.moves[slot] = move;
      mon.pp[slot] = gBattleMoves[move].pp;
}

/** void GiveMonInitialMoveset(struct Pokemon *mon) */
export function GiveMonInitialMoveset(mon: any): any {
  GiveBoxMonInitialMoveset(mon.box);
}

/** void GiveBoxMonInitialMoveset(struct BoxPokemon *boxMon) */
export function GiveBoxMonInitialMoveset(boxMon: any): any {
  let species: any = GetBoxMonData(boxMon, MON_DATA_SPECIES, NULL);
      let level: any = GetLevelFromBoxMonExp(boxMon);
      let i: any = null;

      for (i = 0; gLevelUpLearnsets[species][i] != LEVEL_UP_END; i++)
      {
          let moveLevel: any = null;
          let move: any = null;

          moveLevel = (gLevelUpLearnsets[species][i] & LEVEL_UP_MOVE_LV);

          if (moveLevel > (level << 9))
              break;

          move = (gLevelUpLearnsets[species][i] & LEVEL_UP_MOVE_ID);

          if (GiveMoveToBoxMon(boxMon, move) == MON_HAS_MAX_MOVES)
              DeleteFirstMoveAndGiveMoveToBoxMon(boxMon, move);
      }
}

/** u16 MonTryLearningNewMove(struct Pokemon *mon, bool8 firstMove) */
export function MonTryLearningNewMove(mon: any, firstMove: any): any {
  let retVal: any = MOVE_NONE;
      let species: any = GetMonData(mon, MON_DATA_SPECIES, NULL);
      let level: any = GetMonData(mon, MON_DATA_LEVEL, NULL);

       
       
       
       
      if (firstMove)
      {
          sLearningMoveTableID = 0;

          while ((gLevelUpLearnsets[species][sLearningMoveTableID] & LEVEL_UP_MOVE_LV) != (level << 9))
          {
              sLearningMoveTableID++;
              if (gLevelUpLearnsets[species][sLearningMoveTableID] == LEVEL_UP_END)
                  return MOVE_NONE;
          }
      }

      if ((gLevelUpLearnsets[species][sLearningMoveTableID] & LEVEL_UP_MOVE_LV) == (level << 9))
      {
          gMoveToLearn = (gLevelUpLearnsets[species][sLearningMoveTableID] & LEVEL_UP_MOVE_ID);
          sLearningMoveTableID++;
          retVal = GiveMoveToMon(mon, gMoveToLearn);
      }

      return retVal;
}

/** void DeleteFirstMoveAndGiveMoveToMon(struct Pokemon *mon, u16 move) */
export function DeleteFirstMoveAndGiveMoveToMon(mon: any, move: any): any {
  let i: any = null;
      const moves: any[] = [];
      const pp: any[] = [];
      let ppBonuses: any = null;

      for (i = 0; i < MAX_MON_MOVES - 1; i++)
      {
          moves[i] = GetMonData(mon, MON_DATA_MOVE2 + i, NULL);
          pp[i] = GetMonData(mon, MON_DATA_PP2 + i, NULL);
      }

      ppBonuses = GetMonData(mon, MON_DATA_PP_BONUSES, NULL);
      ppBonuses >>= 2;
      moves[MAX_MON_MOVES - 1] = move;
      pp[MAX_MON_MOVES - 1] = gBattleMoves[move].pp;

      for (i = 0; i < MAX_MON_MOVES; i++)
      {
          SetMonData(mon, MON_DATA_MOVE1 + i,moves[i]);
          SetMonData(mon, MON_DATA_PP1 + i,pp[i]);
      }

      SetMonData(mon, MON_DATA_PP_BONUSES,ppBonuses);
}

/** void DeleteFirstMoveAndGiveMoveToBoxMon(struct BoxPokemon *boxMon, u16 move) */
export function DeleteFirstMoveAndGiveMoveToBoxMon(boxMon: any, move: any): any {
  let i: any = null;
      const moves: any[] = [];
      const pp: any[] = [];
      let ppBonuses: any = null;

      for (i = 0; i < MAX_MON_MOVES - 1; i++)
      {
          moves[i] = GetBoxMonData(boxMon, MON_DATA_MOVE2 + i, NULL);
          pp[i] = GetBoxMonData(boxMon, MON_DATA_PP2 + i, NULL);
      }

      ppBonuses = GetBoxMonData(boxMon, MON_DATA_PP_BONUSES, NULL);
      ppBonuses >>= 2;
      moves[MAX_MON_MOVES - 1] = move;
      pp[MAX_MON_MOVES - 1] = gBattleMoves[move].pp;

      for (i = 0; i < MAX_MON_MOVES; i++)
      {
          SetBoxMonData(boxMon, MON_DATA_MOVE1 + i,moves[i]);
          SetBoxMonData(boxMon, MON_DATA_PP1 + i,pp[i]);
      }

      SetBoxMonData(boxMon, MON_DATA_PP_BONUSES,ppBonuses);
}

/** s32 CalculateBaseDamage(struct BattlePokemon *attacker, struct BattlePokemon *defender, u32 move, u16 sideStatus, u16 powerOverride, u8 typeOverride, u8 battlerIdAtk, u8 battlerIdDef) */
export function CalculateBaseDamage(attacker: any, defender: any, move: any, sideStatus: any, powerOverride: any, typeOverride: any, battlerIdAtk: any, battlerIdDef: any): any {
  let i: any = null;
      let damage: any = 0;
      let damageHelper: any = null;
      let type: any = null;
      let attack, defense;
      let spAttack, spDefense;
      let defenderHoldEffect: any = null;
      let defenderHoldEffectParam: any = null;
      let attackerHoldEffect: any = null;
      let attackerHoldEffectParam: any = null;

      if (!powerOverride)
          gBattleMovePower = gBattleMoves[move].power;
      else
          gBattleMovePower = powerOverride;

      if (!typeOverride)
          type = gBattleMoves[move].type;
      else
          type = typeOverride & DYNAMIC_TYPE_MASK;

      attack = attacker.attack;
      defense = defender.defense;
      spAttack = attacker.spAttack;
      spDefense = defender.spDefense;

       
      if (attacker.item == ITEM_ENIGMA_BERRY)
      {
          attackerHoldEffect = gEnigmaBerries[battlerIdAtk].holdEffect;
          attackerHoldEffectParam = gEnigmaBerries[battlerIdAtk].holdEffectParam;
      }
      else
      {
          attackerHoldEffect = GetItemHoldEffect(attacker.item);
          attackerHoldEffectParam = GetItemHoldEffectParam(attacker.item);
      }

       
      if (defender.item == ITEM_ENIGMA_BERRY)
      {
          defenderHoldEffect = gEnigmaBerries[battlerIdDef].holdEffect;
          defenderHoldEffectParam = gEnigmaBerries[battlerIdDef].holdEffectParam;
      }
      else
      {
          defenderHoldEffect = GetItemHoldEffect(defender.item);
          defenderHoldEffectParam = GetItemHoldEffectParam(defender.item);
      }

      if (attacker.ability == ABILITY_HUGE_POWER || attacker.ability == ABILITY_PURE_POWER)
          attack *= 2;

      if (ShouldGetStatBadgeBoost(FLAG_BADGE01_GET, battlerIdAtk))
          attack = (110 * attack) / 100;
      if (ShouldGetStatBadgeBoost(FLAG_BADGE05_GET, battlerIdDef))
          defense = (110 * defense) / 100;
      if (ShouldGetStatBadgeBoost(FLAG_BADGE07_GET, battlerIdAtk))
          spAttack = (110 * spAttack) / 100;
      if (ShouldGetStatBadgeBoost(FLAG_BADGE07_GET, battlerIdDef))
          spDefense = (110 * spDefense) / 100;

       
      for (i = 0; i < ARRAY_COUNT(sHoldEffectToType); i++)
      {
          if (attackerHoldEffect == sHoldEffectToType[i][0]
              && type == sHoldEffectToType[i][1])
          {
              if (IS_TYPE_PHYSICAL(type))
                  attack = (attack * (attackerHoldEffectParam + 100)) / 100;
              else
                  spAttack = (spAttack * (attackerHoldEffectParam + 100)) / 100;
              break;
          }
      }

       
      if (attackerHoldEffect == HOLD_EFFECT_CHOICE_BAND)
          attack = (150 * attack) / 100;
      if (attackerHoldEffect == HOLD_EFFECT_SOUL_DEW && !(gBattleTypeFlags & (BATTLE_TYPE_FRONTIER)) && (attacker.species == SPECIES_LATIAS || attacker.species == SPECIES_LATIOS))
          spAttack = (150 * spAttack) / 100;
      if (defenderHoldEffect == HOLD_EFFECT_SOUL_DEW && !(gBattleTypeFlags & (BATTLE_TYPE_FRONTIER)) && (defender.species == SPECIES_LATIAS || defender.species == SPECIES_LATIOS))
          spDefense = (150 * spDefense) / 100;
      if (attackerHoldEffect == HOLD_EFFECT_DEEP_SEA_TOOTH && attacker.species == SPECIES_CLAMPERL)
          spAttack *= 2;
      if (defenderHoldEffect == HOLD_EFFECT_DEEP_SEA_SCALE && defender.species == SPECIES_CLAMPERL)
          spDefense *= 2;
      if (attackerHoldEffect == HOLD_EFFECT_LIGHT_BALL && attacker.species == SPECIES_PIKACHU)
          spAttack *= 2;
      if (defenderHoldEffect == HOLD_EFFECT_METAL_POWDER && defender.species == SPECIES_DITTO)
          defense *= 2;
      if (attackerHoldEffect == HOLD_EFFECT_THICK_CLUB && (attacker.species == SPECIES_CUBONE || attacker.species == SPECIES_MAROWAK))
          attack *= 2;

       
      if (defender.ability == ABILITY_THICK_FAT && (type == TYPE_FIRE || type == TYPE_ICE))
          spAttack /= 2;
      if (attacker.ability == ABILITY_HUSTLE)
          attack = (150 * attack) / 100;
      if (attacker.ability == ABILITY_PLUS && ABILITY_ON_FIELD2(ABILITY_MINUS))
          spAttack = (150 * spAttack) / 100;
      if (attacker.ability == ABILITY_MINUS && ABILITY_ON_FIELD2(ABILITY_PLUS))
          spAttack = (150 * spAttack) / 100;
      if (attacker.ability == ABILITY_GUTS && attacker.status1)
          attack = (150 * attack) / 100;
      if (defender.ability == ABILITY_MARVEL_SCALE && defender.status1)
          defense = (150 * defense) / 100;
      if (type == TYPE_ELECTRIC && AbilityBattleEffects(ABILITYEFFECT_FIELD_SPORT, 0, 0, ABILITYEFFECT_MUD_SPORT, 0))
          gBattleMovePower /= 2;
      if (type == TYPE_FIRE && AbilityBattleEffects(ABILITYEFFECT_FIELD_SPORT, 0, 0, ABILITYEFFECT_WATER_SPORT, 0))
          gBattleMovePower /= 2;
      if (type == TYPE_GRASS && attacker.ability == ABILITY_OVERGROW && attacker.hp <= (attacker.maxHP / 3))
          gBattleMovePower = (150 * gBattleMovePower) / 100;
      if (type == TYPE_FIRE && attacker.ability == ABILITY_BLAZE && attacker.hp <= (attacker.maxHP / 3))
          gBattleMovePower = (150 * gBattleMovePower) / 100;
      if (type == TYPE_WATER && attacker.ability == ABILITY_TORRENT && attacker.hp <= (attacker.maxHP / 3))
          gBattleMovePower = (150 * gBattleMovePower) / 100;
      if (type == TYPE_BUG && attacker.ability == ABILITY_SWARM && attacker.hp <= (attacker.maxHP / 3))
          gBattleMovePower = (150 * gBattleMovePower) / 100;

       
      if (gBattleMoves[gCurrentMove].effect == EFFECT_EXPLOSION)
          defense /= 2;

      if (IS_TYPE_PHYSICAL(type))
      {
          if (gCritMultiplier == 2)
          {
               
              if (attacker.statStages[STAT_ATK] > DEFAULT_STAT_STAGE)
                  APPLY_STAT_MOD(damage, attacker, attack, STAT_ATK)
              else
                  damage = attack;
          }
          else
              APPLY_STAT_MOD(damage, attacker, attack, STAT_ATK)

          damage = damage * gBattleMovePower;
          damage *= (2 * attacker.level / 5 + 2);

          if (gCritMultiplier == 2)
          {
               
              if (defender.statStages[STAT_DEF] < DEFAULT_STAT_STAGE)
                  APPLY_STAT_MOD(damageHelper, defender, defense, STAT_DEF)
              else
                  damageHelper = defense;
          }
          else
              APPLY_STAT_MOD(damageHelper, defender, defense, STAT_DEF)

          damage = damage / damageHelper;
          damage /= 50;

           
          if ((attacker.status1 & STATUS1_BURN) && attacker.ability != ABILITY_GUTS)
              damage /= 2;

           
          if ((sideStatus & SIDE_STATUS_REFLECT) && gCritMultiplier == 1)
          {
              if ((gBattleTypeFlags & BATTLE_TYPE_DOUBLE) && CountAliveMonsInBattle(BATTLE_ALIVE_DEF_SIDE) == 2)
                  damage = 2 * (damage / 3);
              else
                  damage /= 2;
          }

           
          if ((gBattleTypeFlags & BATTLE_TYPE_DOUBLE) && gBattleMoves[move].target == MOVE_TARGET_BOTH && CountAliveMonsInBattle(BATTLE_ALIVE_DEF_SIDE) == 2)
              damage /= 2;

           
          if (damage == 0)
              damage = 1;
      }

      if (type == TYPE_MYSTERY)
          damage = 0;  

      if (IS_TYPE_SPECIAL(type))
      {
          if (gCritMultiplier == 2)
          {
               
              if (attacker.statStages[STAT_SPATK] > DEFAULT_STAT_STAGE)
                  APPLY_STAT_MOD(damage, attacker, spAttack, STAT_SPATK)
              else
                  damage = spAttack;
          }
          else
              APPLY_STAT_MOD(damage, attacker, spAttack, STAT_SPATK)

          damage = damage * gBattleMovePower;
          damage *= (2 * attacker.level / 5 + 2);

          if (gCritMultiplier == 2)
          {
               
              if (defender.statStages[STAT_SPDEF] < DEFAULT_STAT_STAGE)
                  APPLY_STAT_MOD(damageHelper, defender, spDefense, STAT_SPDEF)
              else
                  damageHelper = spDefense;
          }
          else
              APPLY_STAT_MOD(damageHelper, defender, spDefense, STAT_SPDEF)

          damage = (damage / damageHelper);
          damage /= 50;

           
          if ((sideStatus & SIDE_STATUS_LIGHTSCREEN) && gCritMultiplier == 1)
          {
              if ((gBattleTypeFlags & BATTLE_TYPE_DOUBLE) && CountAliveMonsInBattle(BATTLE_ALIVE_DEF_SIDE) == 2)
                  damage = 2 * (damage / 3);
              else
                  damage /= 2;
          }

           
          if ((gBattleTypeFlags & BATTLE_TYPE_DOUBLE) && gBattleMoves[move].target == MOVE_TARGET_BOTH && CountAliveMonsInBattle(BATTLE_ALIVE_DEF_SIDE) == 2)
              damage /= 2;

           
          if (WEATHER_HAS_EFFECT2)
          {
               
              if (gBattleWeather & B_WEATHER_RAIN_TEMPORARY)
              {
                  switch (type)
                  {
                  case TYPE_FIRE:
                      damage /= 2;
                      break;
                  case TYPE_WATER:
                      damage = (15 * damage) / 10;
                      break;
                  }
              }

               
              if ((gBattleWeather & (B_WEATHER_RAIN | B_WEATHER_SANDSTORM | B_WEATHER_HAIL)) && gCurrentMove == MOVE_SOLAR_BEAM)
                  damage /= 2;

               
              if (gBattleWeather & B_WEATHER_SUN)
              {
                  switch (type)
                  {
                  case TYPE_FIRE:
                      damage = (15 * damage) / 10;
                      break;
                  case TYPE_WATER:
                      damage /= 2;
                      break;
                  }
              }
          }

           
          if ((gBattleResources.flags.flags[battlerIdAtk] & RESOURCE_FLAG_FLASH_FIRE) && type == TYPE_FIRE)
              damage = (15 * damage) / 10;
      }

      return damage + 2;
}

/** u8 CountAliveMonsInBattle(u8 caseId) */
export function CountAliveMonsInBattle(caseId: any): any {
  let i: any = null;
      let retVal: any = 0;

      switch (caseId)
      {
      case BATTLE_ALIVE_EXCEPT_ACTIVE:
          for (i = 0; i < MAX_BATTLERS_COUNT; i++)
          {
              if (i != gActiveBattler && !(gAbsentBattlerFlags & gBitTable[i]))
                  retVal++;
          }
          break;
      case BATTLE_ALIVE_ATK_SIDE:
          for (i = 0; i < MAX_BATTLERS_COUNT; i++)
          {
              if (GetBattlerSide(i) == GetBattlerSide(gBattlerAttacker) && !(gAbsentBattlerFlags & gBitTable[i]))
                  retVal++;
          }
          break;
      case BATTLE_ALIVE_DEF_SIDE:
          for (i = 0; i < MAX_BATTLERS_COUNT; i++)
          {
              if (GetBattlerSide(i) == GetBattlerSide(gBattlerTarget) && !(gAbsentBattlerFlags & gBitTable[i]))
                  retVal++;
          }
          break;
      }

      return retVal;
}

/** static bool8 ShouldGetStatBadgeBoost(u16 badgeFlag, u8 battler) */
export function ShouldGetStatBadgeBoost(badgeFlag: any, battler: any): any {
  if (gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_EREADER_TRAINER | BATTLE_TYPE_RECORDED_LINK | BATTLE_TYPE_FRONTIER))
          return FALSE;
      else if (GetBattlerSide(battler) != B_SIDE_PLAYER)
          return FALSE;
      else if (gBattleTypeFlags & BATTLE_TYPE_TRAINER && gTrainerBattleOpponent_A == TRAINER_SECRET_BASE)
          return FALSE;
      else if (FlagGet(badgeFlag))
          return TRUE;
      else
          return FALSE;
}

/** u8 GetDefaultMoveTarget(u8 battler) */
export function GetDefaultMoveTarget(battler: any): any {
  let opposing: any = BATTLE_OPPOSITE(GET_BATTLER_SIDE(battler));

      if (!(gBattleTypeFlags & BATTLE_TYPE_DOUBLE))
          return GetBattlerAtPosition(opposing);
      if (CountAliveMonsInBattle(BATTLE_ALIVE_EXCEPT_ACTIVE) > 1)
      {
          let position: any = null;

          if ((Random() & 1) == 0)
              position = BATTLE_PARTNER(opposing);
          else
              position = opposing;

          return GetBattlerAtPosition(position);
      }
      else
      {
          if ((gAbsentBattlerFlags & gBitTable[opposing]))
              return GetBattlerAtPosition(BATTLE_PARTNER(opposing));
          else
              return GetBattlerAtPosition(opposing);
      }
}

/** u8 GetMonGender(struct Pokemon *mon) */
export function GetMonGender(mon: any): any {
  return GetBoxMonGender(mon.box);
}

/** u8 GetBoxMonGender(struct BoxPokemon *boxMon) */
export function GetBoxMonGender(boxMon: any): any {
  let species: any = GetBoxMonData(boxMon, MON_DATA_SPECIES, NULL);
      let personality: any = GetBoxMonData(boxMon, MON_DATA_PERSONALITY, NULL);

      switch (gSpeciesInfo[species].genderRatio)
      {
      case MON_MALE:
      case MON_FEMALE:
      case MON_GENDERLESS:
          return gSpeciesInfo[species].genderRatio;
      }

      if (gSpeciesInfo[species].genderRatio > (personality & 0xFF))
          return MON_FEMALE;
      else
          return MON_MALE;
}

/** u8 GetGenderFromSpeciesAndPersonality(u16 species, u32 personality) */
export function GetGenderFromSpeciesAndPersonality(species: any, personality: any): any {
  switch (gSpeciesInfo[species].genderRatio)
      {
      case MON_MALE:
      case MON_FEMALE:
      case MON_GENDERLESS:
          return gSpeciesInfo[species].genderRatio;
      }

      if (gSpeciesInfo[species].genderRatio > (personality & 0xFF))
          return MON_FEMALE;
      else
          return MON_MALE;
}

/** void SetMultiuseSpriteTemplateToPokemon(u16 speciesTag, u8 battlerPosition) */
export function SetMultiuseSpriteTemplateToPokemon(speciesTag: any, battlerPosition: any): any {
  if (gMonSpritesGfxPtr != NULL)
          gMultiuseSpriteTemplate = gMonSpritesGfxPtr.templates[battlerPosition];
      else if (sMonSpritesGfxManagers[MON_SPR_GFX_MANAGER_A])
          gMultiuseSpriteTemplate = sMonSpritesGfxManagers[MON_SPR_GFX_MANAGER_A].templates[battlerPosition];
      else if (sMonSpritesGfxManagers[MON_SPR_GFX_MANAGER_B])
          gMultiuseSpriteTemplate = sMonSpritesGfxManagers[MON_SPR_GFX_MANAGER_B].templates[battlerPosition];
      else
          gMultiuseSpriteTemplate = gBattlerSpriteTemplates[battlerPosition];

      gMultiuseSpriteTemplate.paletteTag = speciesTag;
      if (battlerPosition == B_POSITION_PLAYER_LEFT || battlerPosition == B_POSITION_PLAYER_RIGHT)
          gMultiuseSpriteTemplate.anims = gAnims_MonPic;
      else if (speciesTag > SPECIES_SHINY_TAG)
          gMultiuseSpriteTemplate.anims = gMonFrontAnimsPtrTable[speciesTag - SPECIES_SHINY_TAG];
      else
          gMultiuseSpriteTemplate.anims = gMonFrontAnimsPtrTable[speciesTag];
}

