/** static void EncryptBoxMon(struct BoxPokemon *boxMon) */
export function EncryptBoxMon(boxMon: any): any {
  let i: any = null;
      for (i = 0; i < ARRAY_COUNT(boxMon.secure.raw); i++)
      {
          boxMon.secure.raw[i] ^= boxMon.personality;
          boxMon.secure.raw[i] ^= boxMon.otId;
      }
}

/** static void DecryptBoxMon(struct BoxPokemon *boxMon) */
export function DecryptBoxMon(boxMon: any): any {
  let i: any = null;
      for (i = 0; i < ARRAY_COUNT(boxMon.secure.raw); i++)
      {
          boxMon.secure.raw[i] ^= boxMon.otId;
          boxMon.secure.raw[i] ^= boxMon.personality;
      }
}

/** u32 GetMonData3(struct Pokemon *mon, s32 field, u8 *data) */
export function GetMonData3(mon: any, field: any, data: any): any {
  let ret: any = null;

      switch (field)
      {
      case MON_DATA_STATUS:
          ret = mon.status;
          break;
      case MON_DATA_LEVEL:
          ret = mon.level;
          break;
      case MON_DATA_HP:
          ret = mon.hp;
          break;
      case MON_DATA_MAX_HP:
          ret = mon.maxHP;
          break;
      case MON_DATA_ATK:
          ret = GetDeoxysStat(mon, STAT_ATK);
          if (!ret)
              ret = mon.attack;
          break;
      case MON_DATA_DEF:
          ret = GetDeoxysStat(mon, STAT_DEF);
          if (!ret)
              ret = mon.defense;
          break;
      case MON_DATA_SPEED:
          ret = GetDeoxysStat(mon, STAT_SPEED);
          if (!ret)
              ret = mon.speed;
          break;
      case MON_DATA_SPATK:
          ret = GetDeoxysStat(mon, STAT_SPATK);
          if (!ret)
              ret = mon.spAttack;
          break;
      case MON_DATA_SPDEF:
          ret = GetDeoxysStat(mon, STAT_SPDEF);
          if (!ret)
              ret = mon.spDefense;
          break;
      case MON_DATA_ATK2:
          ret = mon.attack;
          break;
      case MON_DATA_DEF2:
          ret = mon.defense;
          break;
      case MON_DATA_SPEED2:
          ret = mon.speed;
          break;
      case MON_DATA_SPATK2:
          ret = mon.spAttack;
          break;
      case MON_DATA_SPDEF2:
          ret = mon.spDefense;
          break;
      case MON_DATA_MAIL:
          ret = mon.mail;
          break;
      default:
          ret = GetBoxMonData(mon.box, field, data);
          break;
      }
      return ret;
}

/** u32 GetBoxMonData3(struct BoxPokemon *boxMon, s32 field, u8 *data) */
export function GetBoxMonData3(boxMon: any, field: any, data: any): any {
  let i: any = null;
      let retVal: any = 0;
      let substruct0: any = NULL;
      let substruct1: any = NULL;
      let substruct2: any = NULL;
      let substruct3: any = NULL;

       
      if (field > MON_DATA_ENCRYPT_SEPARATOR)
      {
          substruct0 =(GetSubstruct(boxMon, boxMon.personality, 0).type0);
          substruct1 =(GetSubstruct(boxMon, boxMon.personality, 1).type1);
          substruct2 =(GetSubstruct(boxMon, boxMon.personality, 2).type2);
          substruct3 =(GetSubstruct(boxMon, boxMon.personality, 3).type3);

          DecryptBoxMon(boxMon);

          if (CalculateBoxMonChecksum(boxMon) != boxMon.checksum)
          {
              boxMon.isBadEgg = TRUE;
              boxMon.isEgg = TRUE;
              substruct3.isEgg = TRUE;
          }
      }

      switch (field)
      {
      case MON_DATA_PERSONALITY:
          retVal = boxMon.personality;
          break;
      case MON_DATA_OT_ID:
          retVal = boxMon.otId;
          break;
      case MON_DATA_NICKNAME:
      {
          if (boxMon.isBadEgg)
          {
              for (retVal = 0;
                  retVal < POKEMON_NAME_LENGTH && gText_BadEgg[retVal] != EOS;
                  data[retVal] = gText_BadEgg[retVal], retVal++) {}

              data[retVal] = EOS;
          }
          else if (boxMon.isEgg)
          {
              StringCopy(data, gText_EggNickname);
              retVal = StringLength(data);
          }
          else if (boxMon.language == LANGUAGE_JAPANESE)
          {
              data[0] = EXT_CTRL_CODE_BEGIN;
              data[1] = EXT_CTRL_CODE_JPN;

              for (retVal = 2, i = 0;
                  i < 5 && boxMon.nickname[i] != EOS;
                  data[retVal] = boxMon.nickname[i], retVal++, i++) {}

              data[retVal++] = EXT_CTRL_CODE_BEGIN;
              data[retVal++] = EXT_CTRL_CODE_ENG;
              data[retVal] = EOS;
          }
          else
          {
              for (retVal = 0;
                  retVal < POKEMON_NAME_LENGTH;
                  data[retVal] = boxMon.nickname[retVal], retVal++){}

              data[retVal] = EOS;
          }
          break;
      }
      case MON_DATA_LANGUAGE:
          retVal = boxMon.language;
          break;
      case MON_DATA_SANITY_IS_BAD_EGG:
          retVal = boxMon.isBadEgg;
          break;
      case MON_DATA_SANITY_HAS_SPECIES:
          retVal = boxMon.hasSpecies;
          break;
      case MON_DATA_SANITY_IS_EGG:
          retVal = boxMon.isEgg;
          break;
      case MON_DATA_OT_NAME:
      {
          retVal = 0;

          while (retVal < PLAYER_NAME_LENGTH)
          {
              data[retVal] = boxMon.otName[retVal];
              retVal++;
          }

          data[retVal] = EOS;
          break;
      }
      case MON_DATA_MARKINGS:
          retVal = boxMon.markings;
          break;
      case MON_DATA_CHECKSUM:
          retVal = boxMon.checksum;
          break;
      case MON_DATA_ENCRYPT_SEPARATOR:
          retVal = boxMon.unknown;
          break;
      case MON_DATA_SPECIES:
          retVal = boxMon.isBadEgg ? SPECIES_EGG : substruct0.species;
          break;
      case MON_DATA_HELD_ITEM:
          retVal = substruct0.heldItem;
          break;
      case MON_DATA_EXP:
          retVal = substruct0.experience;
          break;
      case MON_DATA_PP_BONUSES:
          retVal = substruct0.ppBonuses;
          break;
      case MON_DATA_FRIENDSHIP:
          retVal = substruct0.friendship;
          break;
      case MON_DATA_MOVE1:
      case MON_DATA_MOVE2:
      case MON_DATA_MOVE3:
      case MON_DATA_MOVE4:
          retVal = substruct1.moves[field - MON_DATA_MOVE1];
          break;
      case MON_DATA_PP1:
      case MON_DATA_PP2:
      case MON_DATA_PP3:
      case MON_DATA_PP4:
          retVal = substruct1.pp[field - MON_DATA_PP1];
          break;
      case MON_DATA_HP_EV:
          retVal = substruct2.hpEV;
          break;
      case MON_DATA_ATK_EV:
          retVal = substruct2.attackEV;
          break;
      case MON_DATA_DEF_EV:
          retVal = substruct2.defenseEV;
          break;
      case MON_DATA_SPEED_EV:
          retVal = substruct2.speedEV;
          break;
      case MON_DATA_SPATK_EV:
          retVal = substruct2.spAttackEV;
          break;
      case MON_DATA_SPDEF_EV:
          retVal = substruct2.spDefenseEV;
          break;
      case MON_DATA_COOL:
          retVal = substruct2.cool;
          break;
      case MON_DATA_BEAUTY:
          retVal = substruct2.beauty;
          break;
      case MON_DATA_CUTE:
          retVal = substruct2.cute;
          break;
      case MON_DATA_SMART:
          retVal = substruct2.smart;
          break;
      case MON_DATA_TOUGH:
          retVal = substruct2.tough;
          break;
      case MON_DATA_SHEEN:
          retVal = substruct2.sheen;
          break;
      case MON_DATA_POKERUS:
          retVal = substruct3.pokerus;
          break;
      case MON_DATA_MET_LOCATION:
          retVal = substruct3.metLocation;
          break;
      case MON_DATA_MET_LEVEL:
          retVal = substruct3.metLevel;
          break;
      case MON_DATA_MET_GAME:
          retVal = substruct3.metGame;
          break;
      case MON_DATA_POKEBALL:
          retVal = substruct3.pokeball;
          break;
      case MON_DATA_OT_GENDER:
          retVal = substruct3.otGender;
          break;
      case MON_DATA_HP_IV:
          retVal = substruct3.hpIV;
          break;
      case MON_DATA_ATK_IV:
          retVal = substruct3.attackIV;
          break;
      case MON_DATA_DEF_IV:
          retVal = substruct3.defenseIV;
          break;
      case MON_DATA_SPEED_IV:
          retVal = substruct3.speedIV;
          break;
      case MON_DATA_SPATK_IV:
          retVal = substruct3.spAttackIV;
          break;
      case MON_DATA_SPDEF_IV:
          retVal = substruct3.spDefenseIV;
          break;
      case MON_DATA_IS_EGG:
          retVal = substruct3.isEgg;
          break;
      case MON_DATA_ABILITY_NUM:
          retVal = substruct3.abilityNum;
          break;
      case MON_DATA_COOL_RIBBON:
          retVal = substruct3.coolRibbon;
          break;
      case MON_DATA_BEAUTY_RIBBON:
          retVal = substruct3.beautyRibbon;
          break;
      case MON_DATA_CUTE_RIBBON:
          retVal = substruct3.cuteRibbon;
          break;
      case MON_DATA_SMART_RIBBON:
          retVal = substruct3.smartRibbon;
          break;
      case MON_DATA_TOUGH_RIBBON:
          retVal = substruct3.toughRibbon;
          break;
      case MON_DATA_CHAMPION_RIBBON:
          retVal = substruct3.championRibbon;
          break;
      case MON_DATA_WINNING_RIBBON:
          retVal = substruct3.winningRibbon;
          break;
      case MON_DATA_VICTORY_RIBBON:
          retVal = substruct3.victoryRibbon;
          break;
      case MON_DATA_ARTIST_RIBBON:
          retVal = substruct3.artistRibbon;
          break;
      case MON_DATA_EFFORT_RIBBON:
          retVal = substruct3.effortRibbon;
          break;
      case MON_DATA_MARINE_RIBBON:
          retVal = substruct3.marineRibbon;
          break;
      case MON_DATA_LAND_RIBBON:
          retVal = substruct3.landRibbon;
          break;
      case MON_DATA_SKY_RIBBON:
          retVal = substruct3.skyRibbon;
          break;
      case MON_DATA_COUNTRY_RIBBON:
          retVal = substruct3.countryRibbon;
          break;
      case MON_DATA_NATIONAL_RIBBON:
          retVal = substruct3.nationalRibbon;
          break;
      case MON_DATA_EARTH_RIBBON:
          retVal = substruct3.earthRibbon;
          break;
      case MON_DATA_WORLD_RIBBON:
          retVal = substruct3.worldRibbon;
          break;
      case MON_DATA_UNUSED_RIBBONS:
          retVal = substruct3.unusedRibbons;
          break;
      case MON_DATA_MODERN_FATEFUL_ENCOUNTER:
          retVal = substruct3.modernFatefulEncounter;
          break;
      case MON_DATA_SPECIES_OR_EGG:
          retVal = substruct0.species;
          if (substruct0.species && (substruct3.isEgg || boxMon.isBadEgg))
              retVal = SPECIES_EGG;
          break;
      case MON_DATA_IVS:
          retVal = substruct3.hpIV
                | (substruct3.attackIV << 5)
                | (substruct3.defenseIV << 10)
                | (substruct3.speedIV << 15)
                | (substruct3.spAttackIV << 20)
                | (substruct3.spDefenseIV << 25);
          break;
      case MON_DATA_KNOWN_MOVES:
          if (substruct0.species && !substruct3.isEgg)
          {
              let moves: any = data;
              let i: any = 0;

              while (moves[i] != MOVES_COUNT)
              {
                  let move: any = moves[i];
                  if (substruct1.moves[0] == move
                   || substruct1.moves[1] == move
                   || substruct1.moves[2] == move
                   || substruct1.moves[3] == move)
                      retVal |= gBitTable[i];
                  i++;
              }
          }
          break;
      case MON_DATA_RIBBON_COUNT:
          retVal = 0;
          if (substruct0.species && !substruct3.isEgg)
          {
              retVal += substruct3.coolRibbon;
              retVal += substruct3.beautyRibbon;
              retVal += substruct3.cuteRibbon;
              retVal += substruct3.smartRibbon;
              retVal += substruct3.toughRibbon;
              retVal += substruct3.championRibbon;
              retVal += substruct3.winningRibbon;
              retVal += substruct3.victoryRibbon;
              retVal += substruct3.artistRibbon;
              retVal += substruct3.effortRibbon;
              retVal += substruct3.marineRibbon;
              retVal += substruct3.landRibbon;
              retVal += substruct3.skyRibbon;
              retVal += substruct3.countryRibbon;
              retVal += substruct3.nationalRibbon;
              retVal += substruct3.earthRibbon;
              retVal += substruct3.worldRibbon;
          }
          break;
      case MON_DATA_RIBBONS:
          retVal = 0;
          if (substruct0.species && !substruct3.isEgg)
          {
              retVal = substruct3.championRibbon
                  | (substruct3.coolRibbon << 1)
                  | (substruct3.beautyRibbon << 4)
                  | (substruct3.cuteRibbon << 7)
                  | (substruct3.smartRibbon << 10)
                  | (substruct3.toughRibbon << 13)
                  | (substruct3.winningRibbon << 16)
                  | (substruct3.victoryRibbon << 17)
                  | (substruct3.artistRibbon << 18)
                  | (substruct3.effortRibbon << 19)
                  | (substruct3.marineRibbon << 20)
                  | (substruct3.landRibbon << 21)
                  | (substruct3.skyRibbon << 22)
                  | (substruct3.countryRibbon << 23)
                  | (substruct3.nationalRibbon << 24)
                  | (substruct3.earthRibbon << 25)
                  | (substruct3.worldRibbon << 26);
          }
          break;
      default:
          break;
      }

      if (field > MON_DATA_ENCRYPT_SEPARATOR)
          EncryptBoxMon(boxMon);

      return retVal;
}

/** void SetMonData(struct Pokemon *mon, s32 field, const void *dataArg) */
export function SetMonData(mon: any, field: any, dataArg: any): any {
  let data: any = dataArg;

      switch (field)
      {
      case MON_DATA_STATUS:
          SET32(mon.status);
          break;
      case MON_DATA_LEVEL:
          SET8(mon.level);
          break;
      case MON_DATA_HP:
          SET16(mon.hp);
          break;
      case MON_DATA_MAX_HP:
          SET16(mon.maxHP);
          break;
      case MON_DATA_ATK:
          SET16(mon.attack);
          break;
      case MON_DATA_DEF:
          SET16(mon.defense);
          break;
      case MON_DATA_SPEED:
          SET16(mon.speed);
          break;
      case MON_DATA_SPATK:
          SET16(mon.spAttack);
          break;
      case MON_DATA_SPDEF:
          SET16(mon.spDefense);
          break;
      case MON_DATA_MAIL:
          SET8(mon.mail);
          break;
      case MON_DATA_SPECIES_OR_EGG:
          break;
      default:
          SetBoxMonData(mon.box, field, data);
          break;
      }
}

/** void SetBoxMonData(struct BoxPokemon *boxMon, s32 field, const void *dataArg) */
export function SetBoxMonData(boxMon: any, field: any, dataArg: any): any {
  let data: any = dataArg;

      let substruct0: any = NULL;
      let substruct1: any = NULL;
      let substruct2: any = NULL;
      let substruct3: any = NULL;

      if (field > MON_DATA_ENCRYPT_SEPARATOR)
      {
          substruct0 =(GetSubstruct(boxMon, boxMon.personality, 0).type0);
          substruct1 =(GetSubstruct(boxMon, boxMon.personality, 1).type1);
          substruct2 =(GetSubstruct(boxMon, boxMon.personality, 2).type2);
          substruct3 =(GetSubstruct(boxMon, boxMon.personality, 3).type3);

          DecryptBoxMon(boxMon);

          if (CalculateBoxMonChecksum(boxMon) != boxMon.checksum)
          {
              boxMon.isBadEgg = TRUE;
              boxMon.isEgg = TRUE;
              substruct3.isEgg = TRUE;
              EncryptBoxMon(boxMon);
              return;
          }
      }

      switch (field)
      {
      case MON_DATA_PERSONALITY:
          SET32(boxMon.personality);
          break;
      case MON_DATA_OT_ID:
          SET32(boxMon.otId);
          break;
      case MON_DATA_NICKNAME:
      {
          let i: any = null;
          for (i = 0; i < POKEMON_NAME_LENGTH; i++)
              boxMon.nickname[i] = data[i];
          break;
      }
      case MON_DATA_LANGUAGE:
          SET8(boxMon.language);
          break;
      case MON_DATA_SANITY_IS_BAD_EGG:
          SET8(boxMon.isBadEgg);
          break;
      case MON_DATA_SANITY_HAS_SPECIES:
          SET8(boxMon.hasSpecies);
          break;
      case MON_DATA_SANITY_IS_EGG:
          SET8(boxMon.isEgg);
          break;
      case MON_DATA_OT_NAME:
      {
          let i: any = null;
          for (i = 0; i < PLAYER_NAME_LENGTH; i++)
              boxMon.otName[i] = data[i];
          break;
      }
      case MON_DATA_MARKINGS:
          SET8(boxMon.markings);
          break;
      case MON_DATA_CHECKSUM:
          SET16(boxMon.checksum);
          break;
      case MON_DATA_ENCRYPT_SEPARATOR:
          SET16(boxMon.unknown);
          break;
      case MON_DATA_SPECIES:
      {
          SET16(substruct0.species);
          if (substruct0.species)
              boxMon.hasSpecies = TRUE;
          else
              boxMon.hasSpecies = FALSE;
          break;
      }
      case MON_DATA_HELD_ITEM:
          SET16(substruct0.heldItem);
          break;
      case MON_DATA_EXP:
          SET32(substruct0.experience);
          break;
      case MON_DATA_PP_BONUSES:
          SET8(substruct0.ppBonuses);
          break;
      case MON_DATA_FRIENDSHIP:
          SET8(substruct0.friendship);
          break;
      case MON_DATA_MOVE1:
      case MON_DATA_MOVE2:
      case MON_DATA_MOVE3:
      case MON_DATA_MOVE4:
          SET16(substruct1.moves[field - MON_DATA_MOVE1]);
          break;
      case MON_DATA_PP1:
      case MON_DATA_PP2:
      case MON_DATA_PP3:
      case MON_DATA_PP4:
          SET8(substruct1.pp[field - MON_DATA_PP1]);
          break;
      case MON_DATA_HP_EV:
          SET8(substruct2.hpEV);
          break;
      case MON_DATA_ATK_EV:
          SET8(substruct2.attackEV);
          break;
      case MON_DATA_DEF_EV:
          SET8(substruct2.defenseEV);
          break;
      case MON_DATA_SPEED_EV:
          SET8(substruct2.speedEV);
          break;
      case MON_DATA_SPATK_EV:
          SET8(substruct2.spAttackEV);
          break;
      case MON_DATA_SPDEF_EV:
          SET8(substruct2.spDefenseEV);
          break;
      case MON_DATA_COOL:
          SET8(substruct2.cool);
          break;
      case MON_DATA_BEAUTY:
          SET8(substruct2.beauty);
          break;
      case MON_DATA_CUTE:
          SET8(substruct2.cute);
          break;
      case MON_DATA_SMART:
          SET8(substruct2.smart);
          break;
      case MON_DATA_TOUGH:
          SET8(substruct2.tough);
          break;
      case MON_DATA_SHEEN:
          SET8(substruct2.sheen);
          break;
      case MON_DATA_POKERUS:
          SET8(substruct3.pokerus);
          break;
      case MON_DATA_MET_LOCATION:
          SET_BY_WIDTH(substruct3.metLocation);
          break;
      case MON_DATA_MET_LEVEL:
      {
          let metLevel: any = data;
          substruct3.metLevel = metLevel;
          break;
      }
      case MON_DATA_MET_GAME:
          SET8(substruct3.metGame);
          break;
      case MON_DATA_POKEBALL:
      {
          let pokeball: any = data;
          substruct3.pokeball = pokeball;
          break;
      }
      case MON_DATA_OT_GENDER:
          SET8(substruct3.otGender);
          break;
      case MON_DATA_HP_IV:
          SET8(substruct3.hpIV);
          break;
      case MON_DATA_ATK_IV:
          SET8(substruct3.attackIV);
          break;
      case MON_DATA_DEF_IV:
          SET8(substruct3.defenseIV);
          break;
      case MON_DATA_SPEED_IV:
          SET8(substruct3.speedIV);
          break;
      case MON_DATA_SPATK_IV:
          SET8(substruct3.spAttackIV);
          break;
      case MON_DATA_SPDEF_IV:
          SET8(substruct3.spDefenseIV);
          break;
      case MON_DATA_IS_EGG:
          SET8(substruct3.isEgg);
          if (substruct3.isEgg)
              boxMon.isEgg = TRUE;
          else
              boxMon.isEgg = FALSE;
          break;
      case MON_DATA_ABILITY_NUM:
          SET8(substruct3.abilityNum);
          break;
      case MON_DATA_COOL_RIBBON:
          SET8(substruct3.coolRibbon);
          break;
      case MON_DATA_BEAUTY_RIBBON:
          SET8(substruct3.beautyRibbon);
          break;
      case MON_DATA_CUTE_RIBBON:
          SET8(substruct3.cuteRibbon);
          break;
      case MON_DATA_SMART_RIBBON:
          SET8(substruct3.smartRibbon);
          break;
      case MON_DATA_TOUGH_RIBBON:
          SET8(substruct3.toughRibbon);
          break;
      case MON_DATA_CHAMPION_RIBBON:
          SET8(substruct3.championRibbon);
          break;
      case MON_DATA_WINNING_RIBBON:
          SET8(substruct3.winningRibbon);
          break;
      case MON_DATA_VICTORY_RIBBON:
          SET8(substruct3.victoryRibbon);
          break;
      case MON_DATA_ARTIST_RIBBON:
          SET8(substruct3.artistRibbon);
          break;
      case MON_DATA_EFFORT_RIBBON:
          SET8(substruct3.effortRibbon);
          break;
      case MON_DATA_MARINE_RIBBON:
          SET8(substruct3.marineRibbon);
          break;
      case MON_DATA_LAND_RIBBON:
          SET8(substruct3.landRibbon);
          break;
      case MON_DATA_SKY_RIBBON:
          SET8(substruct3.skyRibbon);
          break;
      case MON_DATA_COUNTRY_RIBBON:
          SET8(substruct3.countryRibbon);
          break;
      case MON_DATA_NATIONAL_RIBBON:
          SET8(substruct3.nationalRibbon);
          break;
      case MON_DATA_EARTH_RIBBON:
          SET8(substruct3.earthRibbon);
          break;
      case MON_DATA_WORLD_RIBBON:
          SET8(substruct3.worldRibbon);
          break;
      case MON_DATA_UNUSED_RIBBONS:
          SET8(substruct3.unusedRibbons);
          break;
      case MON_DATA_MODERN_FATEFUL_ENCOUNTER:
          SET8(substruct3.modernFatefulEncounter);
          break;
      case MON_DATA_IVS:
      {
          let ivs: any = data[0] | (data[1] << 8) | (data[2] << 16) | (data[3] << 24);
          substruct3.hpIV = ivs & MAX_IV_MASK;
          substruct3.attackIV = (ivs >> 5) & MAX_IV_MASK;
          substruct3.defenseIV = (ivs >> 10) & MAX_IV_MASK;
          substruct3.speedIV = (ivs >> 15) & MAX_IV_MASK;
          substruct3.spAttackIV = (ivs >> 20) & MAX_IV_MASK;
          substruct3.spDefenseIV = (ivs >> 25) & MAX_IV_MASK;
          break;
      }
      default:
          break;
      }

      if (field > MON_DATA_ENCRYPT_SEPARATOR)
      {
          boxMon.checksum = CalculateBoxMonChecksum(boxMon);
          EncryptBoxMon(boxMon);
      }
}

/** void CopyMon(void *dest, void *src, size_t size) */
export function CopyMon(dest: any, src: any, size: any): any {
  memcpy(dest, src, size);
}

/** u8 GiveMonToPlayer(struct Pokemon *mon) */
export function GiveMonToPlayer(mon: any): any {
  let i: any = null;

      SetMonData(mon, MON_DATA_OT_NAME, gSaveBlock2Ptr.playerName);
      SetMonData(mon, MON_DATA_OT_GENDER,gSaveBlock2Ptr.playerGender);
      SetMonData(mon, MON_DATA_OT_ID, gSaveBlock2Ptr.playerTrainerId);

      for (i = 0; i < PARTY_SIZE; i++)
      {
          if (GetMonData(gPlayerParty[i], MON_DATA_SPECIES, NULL) == SPECIES_NONE)
              break;
      }

      if (i >= PARTY_SIZE)
          return CopyMonToPC(mon);

      CopyMon(gPlayerParty[i], mon, 0);
      gPlayerPartyCount = i + 1;
      return MON_GIVEN_TO_PARTY;
}

/** static u8 CopyMonToPC(struct Pokemon *mon) */
export function CopyMonToPC(mon: any): any {
  let boxNo, boxPos;

      SetPCBoxToSendMon(VarGet(VAR_PC_BOX_TO_SEND_MON));

      boxNo = StorageGetCurrentBox();

      do
      {
          for (boxPos = 0; boxPos < IN_BOX_COUNT; boxPos++)
          {
              let checkingMon: any = GetBoxedMonPtr(boxNo, boxPos);
              if (GetBoxMonData(checkingMon, MON_DATA_SPECIES, NULL) == SPECIES_NONE)
              {
                  MonRestorePP(mon);
                  CopyMon(checkingMon,mon.box, sizeof(mon.box));
                  gSpecialVar_MonBoxId = boxNo;
                  gSpecialVar_MonBoxPos = boxPos;
                  if (GetPCBoxToSendMon() != boxNo)
                      FlagClear(FLAG_SHOWN_BOX_WAS_FULL_MESSAGE);
                  VarSet(VAR_PC_BOX_TO_SEND_MON, boxNo);
                  return MON_GIVEN_TO_PC;
              }
          }

          boxNo++;
          if (boxNo == TOTAL_BOXES_COUNT)
              boxNo = 0;
      } while (boxNo != StorageGetCurrentBox());

      return MON_CANT_GIVE;
}

/** u8 CalculatePlayerPartyCount(void) */
export function CalculatePlayerPartyCount(): any {
  gPlayerPartyCount = 0;

      while (gPlayerPartyCount < PARTY_SIZE
          && GetMonData(gPlayerParty[gPlayerPartyCount], MON_DATA_SPECIES, NULL) != SPECIES_NONE)
      {
          gPlayerPartyCount++;
      }

      return gPlayerPartyCount;
}

/** u8 CalculateEnemyPartyCount(void) */
export function CalculateEnemyPartyCount(): any {
  gEnemyPartyCount = 0;

      while (gEnemyPartyCount < PARTY_SIZE
          && GetMonData(gEnemyParty[gEnemyPartyCount], MON_DATA_SPECIES, NULL) != SPECIES_NONE)
      {
          gEnemyPartyCount++;
      }

      return gEnemyPartyCount;
}

/** u8 GetMonsStateToDoubles(void) */
export function GetMonsStateToDoubles(): any {
  let aliveCount: any = 0;
      let i: any = null;
      CalculatePlayerPartyCount();

      if (gPlayerPartyCount == 1)
          return gPlayerPartyCount;  

      for (i = 0; i < gPlayerPartyCount; i++)
      {
          if (GetMonData(gPlayerParty[i], MON_DATA_SPECIES_OR_EGG, NULL) != SPECIES_EGG
           && GetMonData(gPlayerParty[i], MON_DATA_HP, NULL) != 0
           && GetMonData(gPlayerParty[i], MON_DATA_SPECIES_OR_EGG, NULL) != SPECIES_NONE)
              aliveCount++;
      }

      return (aliveCount > 1) ? PLAYER_HAS_TWO_USABLE_MONS : PLAYER_HAS_ONE_USABLE_MON;
}

/** u8 GetMonsStateToDoubles_2(void) */
export function GetMonsStateToDoubles_2(): any {
  let aliveCount: any = 0;
      let i: any = null;

      for (i = 0; i < PARTY_SIZE; i++)
      {
          let species: any = GetMonData(gPlayerParty[i], MON_DATA_SPECIES_OR_EGG, NULL);
          if (species != SPECIES_EGG && species != SPECIES_NONE
           && GetMonData(gPlayerParty[i], MON_DATA_HP, NULL) != 0)
              aliveCount++;
      }

      if (aliveCount == 1)
          return PLAYER_HAS_ONE_MON;  

      return (aliveCount > 1) ? PLAYER_HAS_TWO_USABLE_MONS : PLAYER_HAS_ONE_USABLE_MON;
}

/** u8 GetAbilityBySpecies(u16 species, u8 abilityNum) */
export function GetAbilityBySpecies(species: any, abilityNum: any): any {
  if (abilityNum)
          gLastUsedAbility = gSpeciesInfo[species].abilities[1];
      else
          gLastUsedAbility = gSpeciesInfo[species].abilities[0];

      return gLastUsedAbility;
}

/** u8 GetMonAbility(struct Pokemon *mon) */
export function GetMonAbility(mon: any): any {
  let species: any = GetMonData(mon, MON_DATA_SPECIES, NULL);
      let abilityNum: any = GetMonData(mon, MON_DATA_ABILITY_NUM, NULL);
      return GetAbilityBySpecies(species, abilityNum);
}

/** void CreateSecretBaseEnemyParty(struct SecretBase *secretBaseRecord) */
export function CreateSecretBaseEnemyParty(secretBaseRecord: any): any {
  let i, j;

      ZeroEnemyPartyMons();
      gBattleResources.secretBase = secretBaseRecord;

      for (i = 0; i < PARTY_SIZE; i++)
      {
          if (gBattleResources.secretBase.party.species[i])
          {
              CreateMon(gEnemyParty[i],
                  gBattleResources.secretBase.party.species[i],
                  gBattleResources.secretBase.party.levels[i],
                  15,
                  TRUE,
                  gBattleResources.secretBase.party.personality[i],
                  OT_ID_RANDOM_NO_SHINY,
                  0);

              SetMonData(gEnemyParty[i], MON_DATA_HELD_ITEM,gBattleResources.secretBase.party.heldItems[i]);

              for (j = 0; j < NUM_STATS; j++)
                  SetMonData(gEnemyParty[i], MON_DATA_HP_EV + j,gBattleResources.secretBase.party.EVs[i]);

              for (j = 0; j < MAX_MON_MOVES; j++)
              {
                  SetMonData(gEnemyParty[i], MON_DATA_MOVE1 + j,gBattleResources.secretBase.party.moves[i * MAX_MON_MOVES + j]);
                  SetMonData(gEnemyParty[i], MON_DATA_PP1 + j,gBattleMoves[gBattleResources.secretBase.party.moves[i * MAX_MON_MOVES + j]].pp);
              }
          }
      }
}

