/** bool8 IsPlayerPartyAndPokemonStorageFull(void) */
export function IsPlayerPartyAndPokemonStorageFull(): any {
  let i: any = null;

      for (i = 0; i < PARTY_SIZE; i++)
          if (GetMonData(gPlayerParty[i], MON_DATA_SPECIES, NULL) == SPECIES_NONE)
              return FALSE;

      return IsPokemonStorageFull();
}

/** bool8 IsPokemonStorageFull(void) */
export function IsPokemonStorageFull(): any {
  let i, j;

      for (i = 0; i < TOTAL_BOXES_COUNT; i++)
          for (j = 0; j < IN_BOX_COUNT; j++)
              if (GetBoxMonDataAt(i, j, MON_DATA_SPECIES) == SPECIES_NONE)
                  return FALSE;

      return TRUE;
}

/** void GetSpeciesName(u8 *name, u16 species) */
export function GetSpeciesName(name: any, species: any): any {
  let i: any = null;

      for (i = 0; i <= POKEMON_NAME_LENGTH; i++)
      {
          if (species > NUM_SPECIES)
              name[i] = gSpeciesNames[SPECIES_NONE][i];
          else
              name[i] = gSpeciesNames[species][i];

          if (name[i] == EOS)
              break;
      }

      name[i] = EOS;
}

/** u8 CalculatePPWithBonus(u16 move, u8 ppBonuses, u8 moveIndex) */
export function CalculatePPWithBonus(move: any, ppBonuses: any, moveIndex: any): any {
  let basePP: any = gBattleMoves[move].pp;
      return basePP + ((basePP * 20 * ((gPPUpGetMask[moveIndex] & ppBonuses) >> (2 * moveIndex))) / 100);
}

/** void RemoveMonPPBonus(struct Pokemon *mon, u8 moveIndex) */
export function RemoveMonPPBonus(mon: any, moveIndex: any): any {
  let ppBonuses: any = GetMonData(mon, MON_DATA_PP_BONUSES, NULL);
      ppBonuses &= gPPUpClearMask[moveIndex];
      SetMonData(mon, MON_DATA_PP_BONUSES,ppBonuses);
}

/** void RemoveBattleMonPPBonus(struct BattlePokemon *mon, u8 moveIndex) */
export function RemoveBattleMonPPBonus(mon: any, moveIndex: any): any {
  mon.ppBonuses &= gPPUpClearMask[moveIndex];
}

