/** u16 ModifyStatByNature(u8 nature, u16 stat, u8 statIndex) */
export function ModifyStatByNature(nature: any, stat: any, statIndex: any): any {
      let retVal: any = null;

       
      if (statIndex <= STAT_HP || statIndex > NUM_NATURE_STATS)
          return stat;

      switch (gNatureStatTable[nature][statIndex - 1])
      {
      case 1:
          retVal = stat * 110;
          retVal /= 100;
          break;
      case -1:
          retVal = stat * 90;
          retVal /= 100;
          break;
      default:
          retVal = stat;
          break;
      }

      return retVal;
}

/** void AdjustFriendship(struct Pokemon *mon, u8 event) */
export function AdjustFriendship(mon: any, event: any): any {
  let species, heldItem;
      let holdEffect: any = null;
      let mod: any = null;

      if (ShouldSkipFriendshipChange())
          return;

      species = GetMonData(mon, MON_DATA_SPECIES_OR_EGG, 0);
      heldItem = GetMonData(mon, MON_DATA_HELD_ITEM, 0);

      if (heldItem == ITEM_ENIGMA_BERRY)
      {
          if (gMain.inBattle)
              holdEffect = gEnigmaBerries[0].holdEffect;
          else
              holdEffect = gSaveBlock1Ptr.enigmaBerry.holdEffect;
      }
      else
      {
          holdEffect = GetItemHoldEffect(heldItem);
      }

      if (species && species != SPECIES_EGG)
      {
          let friendshipLevel: any = 0;
          let friendship: any = GetMonData(mon, MON_DATA_FRIENDSHIP, 0);

          if (friendship > 99)
              friendshipLevel++;
          if (friendship > 199)
              friendshipLevel++;

          if (event == FRIENDSHIP_EVENT_WALKING)
          {
               
              if (Random() & 1)
                  return;
          }
          if (event == FRIENDSHIP_EVENT_LEAGUE_BATTLE)
          {
               
              if (!(gBattleTypeFlags & BATTLE_TYPE_TRAINER))
                  return;
              if (!(gTrainers[gTrainerBattleOpponent_A].trainerClass == TRAINER_CLASS_LEADER
                  || gTrainers[gTrainerBattleOpponent_A].trainerClass == TRAINER_CLASS_ELITE_FOUR
                  || gTrainers[gTrainerBattleOpponent_A].trainerClass == TRAINER_CLASS_CHAMPION))
                  return;
          }

          mod = sFriendshipEventModifiers[event][friendshipLevel];
          if (mod > 0 && holdEffect == HOLD_EFFECT_FRIENDSHIP_UP)
               
              mod = (150 * mod) / 100;

          friendship += mod;
          if (mod > 0)
          {
              if (GetMonData(mon, MON_DATA_POKEBALL, NULL) == ITEM_LUXURY_BALL)
                  friendship++;
              if (GetMonData(mon, MON_DATA_MET_LOCATION, NULL) == GetCurrentRegionMapSectionId())
                  friendship++;
          }

          if (friendship < 0)
              friendship = 0;
          if (friendship > MAX_FRIENDSHIP)
              friendship = MAX_FRIENDSHIP;

          SetMonData(mon, MON_DATA_FRIENDSHIP,friendship);
      }
}

/** void MonGainEVs(struct Pokemon *mon, u16 defeatedSpecies) */
export function MonGainEVs(mon: any, defeatedSpecies: any): any {
  const evs: any[] = [];
      let evIncrease: any = 0;
      let totalEVs: any = 0;
      let heldItem: any = null;
      let holdEffect: any = null;
      let i, multiplier;

      for (i = 0; i < NUM_STATS; i++)
      {
          evs[i] = GetMonData(mon, MON_DATA_HP_EV + i, 0);
          totalEVs += evs[i];
      }

      for (i = 0; i < NUM_STATS; i++)
      {
          if (totalEVs >= MAX_TOTAL_EVS)
              break;

          if (CheckPartyHasHadPokerus(mon, 0))
              multiplier = 2;
          else
              multiplier = 1;

          switch (i)
          {
          case STAT_HP:
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_HP * multiplier;
              break;
          case STAT_ATK:
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_Attack * multiplier;
              break;
          case STAT_DEF:
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_Defense * multiplier;
              break;
          case STAT_SPEED:
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_Speed * multiplier;
              break;
          case STAT_SPATK:
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_SpAttack * multiplier;
              break;
          case STAT_SPDEF:
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_SpDefense * multiplier;
              break;
          }

          heldItem = GetMonData(mon, MON_DATA_HELD_ITEM, 0);
          if (heldItem == ITEM_ENIGMA_BERRY)
          {
              if (gMain.inBattle)
                  holdEffect = gEnigmaBerries[0].holdEffect;
              else
                  holdEffect = gSaveBlock1Ptr.enigmaBerry.holdEffect;
          }
          else
          {
              holdEffect = GetItemHoldEffect(heldItem);
          }

          if (holdEffect == HOLD_EFFECT_MACHO_BRACE)
              evIncrease *= 2;

          if (totalEVs + evIncrease > MAX_TOTAL_EVS)
              evIncrease = (evIncrease + MAX_TOTAL_EVS) - (totalEVs + evIncrease);

          if (evs[i] + evIncrease > MAX_PER_STAT_EVS)
          {
              let val1: any = evIncrease + MAX_PER_STAT_EVS;
              let val2: any = evs[i] + evIncrease;
              evIncrease = val1 - val2;
          }

          evs[i] += evIncrease;
          totalEVs += evIncrease;
          SetMonData(mon, MON_DATA_HP_EV + i,evs[i]);
      }
}

/** u16 GetMonEVCount(struct Pokemon *mon) */
